### 2. Plan de Pruebas Unitarias (Vitest)

Las pruebas unitarias validan la lógica de los reducers de Zustand, la gestión de reintentos y el parseo de esquemas Zod ante eventos concurrentes.

*Archivo de prueba: `src/features/preventas/__tests__/realtime-sync.spec.ts`*

```typescript
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { usePreventasStore } from '../store/preventasStore';
import { ZodPreventaRealtimePayload } from '../schemas/preventaRealtime.schema';

describe('SPEC-045: Sincronización Realtime - Unit Tests', () => {
  beforeEach(() => {
    usePreventasStore.getState().reset();
  });

  it('debe aceptar y actualizar el estado local con un payload válido', () => {
    const validPayload = {
      id: 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
      tenant_id: 'b1eebc99-9c0b-4ef8-bb6d-6bb9bd380a22',
      taquilla_id: 'c2eebc99-9c0b-4ef8-bb6d-6bb9bd380a33',
      estado: 'sincronizada' as const,
      total: 154000.00,
      version: 2,
      updated_at: new Date().toISOString(),
    };

    const parsed = ZodPreventaRealtimePayload.safeParse(validPayload);
    expect(parsed.success).toBe(true);

    if (parsed.success) {
      usePreventasStore.getState().upsertPreventa(parsed.data);
      const preventa = usePreventasStore.getState().preventas[validPayload.id];
      expect(preventa).toEqual(parsed.data);
      expect(preventa.version).toBe(2);
    }
  });

  it('debe rechazar payloads malformados o con tipos incorrectos (Zod Guard)', () => {
    const invalidPayload = {
      id: 'no-es-un-uuid',
      tenant_id: 'b1eebc99-9c0b-4ef8-bb6d-6bb9bd380a22',
      taquilla_id: 'c2eebc99-9c0b-4ef8-bb6d-6bb9bd380a33',
      estado: 'estado_invalido',
      total: -500, // No permitido
      version: 'dos', // Debe ser int
      updated_at: 'fecha-invalida',
    };

    const parsed = ZodPreventaRealtimePayload.safeParse(invalidPayload);
    expect(parsed.success).toBe(false);
  });
});
```

