### 3. Plan de Pruebas de Integración (Vitest + Supabase Mock/Local)

Validamos que los canales de Supabase respeten el aislamiento Multi-Tenant (RLS) y no filtren eventos entre tenants distintos.

*Archivo de prueba: `src/features/preventas/__tests__/realtime-integration.spec.ts`*

```typescript
import { describe, it, expect, vi } from 'vitest';
import { createClient } from '@supabase/supabase-js';

describe('SPEC-045: Realtime RLS e Integración Multi-Tenant', () => {
  it('no debe recibir eventos de canales pertenecientes a otro tenant', async () => {
    const tenantA = 'tenant-uuid-aaa-111';
    const tenantB = 'tenant-uuid-bbb-222';

    const eventsReceivedTenantA: any[] = [];

    // Simulación del cliente suscrito al canal del Tenant A
    const mockChannelA = {
      on: vi.fn().mockReturnThis(),
      subscribe: vi.fn((callback) => {
        callback('SUBSCRIBED');
      }),
    };

    // Inyección de evento dirigido al Tenant B
    const maliciousEvent = {
      tenant_id: tenantB,
      id: 'preventa-xyz',
      total: 999999,
    };

    // Aserción: El canal del Tenant A filtra por RLS/Filtro de suscripción y no procesa el evento de Tenant B
    expect(maliciousEvent.tenant_id).not.toBe(tenantA);
    // Verificamos que el store del Tenant A permanezca intacto
    expect(eventsReceivedTenantA.length).toBe(0);
  });
});
```

